package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
//   - The emphasis pass (__bold__ / _italic_) is extracted into applyEmphasis.
//   - The single character-scanning loop is kept, but its three concerns —
//     headers, list markers and line breaks — are each handled by a small
//     method on renderer, so the loop body reads as a simple dispatch.
//   - The original single-letter variables (he, listOpened, ...) are renamed
//     to describe what they track.
//   - The loop is bounds-checked before each read, so input that ends in a
//     marker no longer panics (the original indexed past the end in that case).
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	r := &renderer{}
	for pos := 0; pos < len(markdown); {
		char := markdown[pos]
		switch {
		case char == '#':
			pos = r.writeHeader(markdown, pos)
		case char == '*' && r.header == 0 && strings.Contains(markdown, "\n"):
			// A '*' only starts a list item in multi-line input that is not
			// inside a header; anywhere else it is copied through as text.
			pos = r.writeListMarker(markdown, pos)
		case char == '\n':
			pos = r.writeLineBreak(markdown, pos)
		default:
			r.html.WriteByte(char)
			pos++
		}
		// Any character other than '#' counts as "text seen"; from then on,
		// '#' runs are treated as literal text rather than header markers.
		if char != '#' {
			r.seenText = true
		}
	}
	return r.finish()
}

// renderer accumulates the HTML output and tracks the parser state while
// scanning the markdown one character at a time.
type renderer struct {
	html      strings.Builder
	header    int  // level of the open header, 0 when not in one
	seenText  bool // set once any non-# character has been written
	listCount int  // how many '*' markers have been consumed
	itemOpen  bool // whether a <li> is currently open
}

// applyEmphasis converts the first __…__ pair to <strong>…</strong> and the
// first _…_ pair to <em>…</em>. Only one of each is converted, matching the
// original implementation.
func applyEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)
	return markdown
}

// writeHeader consumes a run of '#' characters starting at pos and emits the
// matching header markup. It returns the position just past the run and the
// separator character (normally a space) that follows it.
func (r *renderer) writeHeader(markdown string, pos int) int {
	for pos < len(markdown) && markdown[pos] == '#' {
		r.header++
		pos++
	}
	switch {
	case r.header == 7:
		// Seven hashes are not a header; they are kept literally in a paragraph.
		r.html.WriteString(fmt.Sprintf("<p>%s ", strings.Repeat("#", r.header)))
	case r.seenText:
		// A '#' that appears after other content is literal text.
		r.html.WriteString("# ")
		r.header--
	default:
		r.html.WriteString(fmt.Sprintf("<h%d>", r.header))
	}
	return pos + 1
}

// writeListMarker consumes a '*' marker (and the space after it) at pos.
// The first marker opens a <ul>, and each marker while no item is open
// starts a new <li>. A '*' found while an item is still open is treated as
// literal text, which is how mid-item asterisks survive.
func (r *renderer) writeListMarker(markdown string, pos int) int {
	if r.listCount == 0 {
		r.html.WriteString("<ul>")
	}
	r.listCount++
	if r.itemOpen {
		r.html.WriteString("* ")
	} else {
		r.html.WriteString("<li>")
		r.itemOpen = true
	}
	return pos + 2
}

// writeLineBreak handles a '\n' at pos: it closes an open list item, a list
// that ends the document, and any open header.
func (r *renderer) writeLineBreak(markdown string, pos int) int {
	lastNewline := strings.LastIndex(markdown, "\n")
	if r.itemOpen && lastNewline == pos && lastNewline > strings.LastIndex(markdown, "*") {
		// The list is the last thing in the document and a line follows it:
		// close the list and start a paragraph for that trailing line.
		r.html.WriteString("</li></ul><p>")
		r.itemOpen = false
		r.listCount = 0
	} else if r.listCount > 0 && r.itemOpen {
		r.html.WriteString("</li>")
		r.itemOpen = false
	}
	if r.header > 0 {
		r.html.WriteString(fmt.Sprintf("</h%d>", r.header))
		r.header = 0
	}
	return pos + 1
}

// finish closes any markup still open at the end of the input.
func (r *renderer) finish() string {
	switch {
	case r.header == 7:
		r.html.WriteString("</p>")
	case r.header > 0:
		r.html.WriteString(fmt.Sprintf("</h%d>", r.header))
	case r.listCount > 0:
		r.html.WriteString("</li></ul>")
	case strings.Contains(r.html.String(), "<p>"):
		r.html.WriteString("</p>")
	default:
		return "<p>" + r.html.String() + "</p>"
	}
	return r.html.String()
}
